{"content":"# =============================================================================
# ars.R
#
# Adaptive Rejection Sampling (ARS) for log-concave densities, following
# Gilks & Wild (1992), "Adaptive Rejection Sampling for Gibbs Sampling",
# Journal of the Royal Statistical Society, Series C (Applied Statistics),
# 41(2), 337-348.
#
# The target density only needs to be known up to a normalizing constant.
# The user supplies a *vectorized* function computing the (possibly
# unnormalized) density -- e.g. dnorm, dexp -- plus the domain [a, b].
# Log-concavity is checked both when the hull is built and every time a new
# point is added to the hull during sampling.
#
# Contents (consistent snake_case, function-based design):
#   validate_ars_inputs()      validate all user inputs
#   probe_points()             interior probe points for a given domain
#   default_starting_points()  sensible initial abscissae for a domain
#   eval_log_density()         safe, vectorized evaluation of log g(x)
#   log_density_deriv()        numerical derivative of the log-density
#   check_slope_order()        log-concavity check on tangent slopes
#   build_envelope()           upper hull, squeezing function and weights
#   sample_envelope()          draw one proposal from the envelope
#   upper_hull()               evaluate the piecewise-tangent upper hull
#   lower_hull()               evaluate the chord-based squeezing function
#   ars()                      main adaptive rejection sampler
#   test()                     formal test suite against known distributions
#
# Quick examples:
#   source("/app/ars.R")
#   x <- ars(dnorm, n = 1000)                                  # N(0, 1)
#   y <- ars(dexp, n = 1000, a = 0)                            # Exp(1)
#   z <- ars(function(x) dgamma(x, shape = 2), n = 500, a = 0) # extra args
# =============================================================================

# ---------------------------------------------------------------------------
# validate_ars_inputs: check every user input for validity before sampling.
# ---------------------------------------------------------------------------
validate_ars_inputs <- function(g, n, a, b, x0) {
  if (!is.function(g)) {
    stop("'g' must be a function that evaluates the (possibly unnormalized) ",
         "density in a vectorized fashion, e.g. dnorm.", call. = FALSE)
  }
  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) ||
      n <= 0 || n != floor(n)) {
    stop("'n' must be a single positive integer giving the number of samples ",
         "to draw.", call. = FALSE)
  }
  if (length(a) != 1L || length(b) != 1L || !is.numeric(a) ||
      !is.numeric(b) || is.na(a) || is.na(b)) {
    stop("'a' and 'b' must be single numeric values with a < b ",
         "(use -Inf / Inf for unbounded sides).", call. = FALSE)
  }
  if (!(a < b)) {
    stop("'a' must be strictly less than 'b'; got a = ", a, ", b = ", b, ".",
         call. = FALSE)
  }
  if (!is.null(x0)) {
    if (!is.numeric(x0) || any(is.na(x0))) {
      stop("'x0' must be a numeric vector of starting abscissae without NAs.",
           call. = FALSE)
    }
    if (length(x0) < 2L) {
      stop("at least two starting abscissae 'x0' are required to build the ",
           "initial hull.", call. = FALSE)
    }
    if (any(x0 < a | x0 > b)) {
      stop("all starting abscissae 'x0' must lie inside the domain [a, b].",
           call. = FALSE)
    }
    if (length(unique(x0)) != length(x0)) {
      stop("'x0' must contain distinct values.", call. = FALSE)
    }
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# probe_points: two interior points used to check vectorization / sanity.
# ---------------------------------------------------------------------------
probe_points <- function(a, b) {
  if (is.finite(a) && is.finite(b)) {
    return(a + (b - a) * c(0.25, 0.75))
  }
  if (!is.finite(a) && !is.finite(b)) {
    return(c(-1, 1))
  }
  if (is.finite(a)) {
    return(a + c(1, 2))
  }
  b - c(2, 1)
}

# ---------------------------------------------------------------------------
# default_starting_points: sensible initial abscissae for each domain shape.
# ---------------------------------------------------------------------------
default_starting_points <- function(a, b) {
  if (is.finite(a) && is.finite(b)) {
    return(a + (b - a) * c(0.25, 0.5, 0.75))
  }
  if (!is.finite(a) && !is.finite(b)) {
    return(c(-2, -0.5, 0.5, 2))
  }
  if (is.finite(a)) {
    return(a + c(0.5, 1.5, 3))
  }
  b - c(3, 1.5, 0.5)
}

# ---------------------------------------------------------------------------
# eval_log_density: safely evaluate log g(x) in a vectorized fashion.
# Maps zero density to -Inf (a plain rejection); negative densities always
# signal an invalid density function. With strict = TRUE (used for input
# validation), NA/NaN densities are an error; otherwise they map to -Inf.
# ---------------------------------------------------------------------------
eval_log_density <- function(g, x, ..., strict = FALSE) {
  d <- tryCatch(g(x, ...),
                error = function(e) {
                  stop("density function 'g' failed to evaluate: ",
                       conditionMessage(e), call. = FALSE)
                })
  if (!is.numeric(d)) {
    stop("density function 'g' must return a numeric vector.", call. = FALSE)
  }
  if (length(d) != length(x)) {
    stop("density function 'g' must be vectorized: evaluating g at ",
         length(x), " points must return ", length(x), " densities, but got ",
         length(d), ".", call. = FALSE)
  }
  if (any(!is.na(d) & d < 0)) {
    stop("density function 'g' returned negative value(s); densities must ",
         "be non-negative.", call. = FALSE)
  }
  bad <- is.na(d)
  if (strict && any(bad)) {
    stop("density function 'g' returned NA/NaN value(s).", call. = FALSE)
  }
  h <- suppressWarnings(log(d))
  h[bad] <- -Inf
  h
}

# ---------------------------------------------------------------------------
# log_density_deriv: numerical derivative of h(x) = log g(x) by central
# differences, with step-halving and one-sided fallbacks near boundaries.
# ---------------------------------------------------------------------------
log_density_deriv <- function(g, x, ..., h_here = NULL) {
  if (is.null(h_here)) {
    h_here <- eval_log_density(g, x, ...)
  }
  if (any(!is.finite(h_here))) {
    stop("cannot compute the log-density derivative at point(s) with ",
         "zero/non-finite density; choose starting values with positive, ",
         "finite density.", call. = FALSE)
  }
  base_step <- sqrt(.Machine$double.eps) * pmax(1, abs(x))
  deriv <- numeric(length(x))
  for (i in seq_along(x)) {
    step <- base_step[i]
    done <- FALSE
    for (attempt in seq_len(12L)) {
      up <- eval_log_density(g, x[i] + step, ...)[1L]
      lo <- eval_log_density(g, x[i] - step, ...)[1L]
      if (is.finite(up) && is.finite(lo)) {
        deriv[i] <- (up - lo) / (2 * step)
        done <- TRUE
        break
      } else if (is.finite(up) && is.finite(h_here[i])) {
        deriv[i] <- (up - h_here[i]) / step
        done <- TRUE
        break
      } else if (is.finite(lo) && is.finite(h_here[i])) {
        deriv[i] <- (h_here[i] - lo) / step
        done <- TRUE
        break
      }
      step <- step / 2
    }
    if (!done) {
      stop("cannot evaluate the log-density derivative at x = ", x[i], "; ",
           "the density may be zero or discontinuous there. Try different ",
           "starting values.", call. = FALSE)
    }
  }
  deriv
}

# ---------------------------------------------------------------------------
# check_slope_order: for a log-concave h, tangent slopes must be
# non-increasing in x. An increase beyond tolerance means "not log-concave".
# (Equal slopes are fine: they cover log-linear pieces such as the
# exponential or uniform densities.)
# ---------------------------------------------------------------------------
check_slope_order <- function(hp, slope_tol = 1e-7) {
  if (length(hp) < 2L) {
    return(invisible(TRUE))
  }
  if (any(diff(hp) > slope_tol)) {
    stop("density does not appear to be log-concave: the slopes of the ",
         "log-density tangents are not decreasing in x.", call. = FALSE)
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# build_envelope: Gilks & Wild (1992) upper hull u(x) from tangents at the
# abscissae, chord-based squeezing function, and envelope segment weights.
# The envelope density s(x) propto exp(u(x)) is piecewise exponential.
# Weights are computed on the log scale for numerical stability.
# ---------------------------------------------------------------------------
build_envelope <- function(x, h, hp, a, b) {
  k <- length(x)
  slope_tol <- 1e-7 * (1 + max(abs(hp)))
  check_slope_order(hp, slope_tol = slope_tol)

  ## Breakpoints: z_0 = a, z_k = b, interior z_j = tangent intersections.
  z <- numeric(k + 1L)
  z[1L] <- a
  z[k + 1L] <- b
  if (k >= 2L) {
    for (j in seq_len(k - 1L)) {
      denom <- hp[j] - hp[j + 1L]
      if (abs(denom) <= slope_tol) {
        ## (Near-)parallel tangents: any breakpoint between them works.
        z[j + 1L] <- 0.5 * (x[j] + x[j + 1L])
      } else {
        z[j + 1L] <- (h[j + 1L] - h[j] - x[j + 1L] * hp[j + 1L] +
                        x[j] * hp[j]) / denom
      }
    }
    inner <- z[seq_len(k - 1L) + 1L]
    if (any(!is.finite(inner))) {
      stop("density does not appear to be log-concave: tangent intersection ",
           "point(s) are non-finite.", call. = FALSE)
    }
    xtol <- 1e-9 * (1 + max(abs(x)))
    for (j in seq_len(k - 1L)) {
      if (!(z[j + 1L] > x[j] - xtol && z[j + 1L] < x[j + 1L] + xtol)) {
        stop("density does not appear to be log-concave: tangent ",
             "intersection ", j, " does not lie between its abscissae.",
             call. = FALSE)
      }
    }
  }
  if (any(diff(z) <= 0)) {
    stop("density does not appear to be log-concave: envelope breakpoints ",
         "are not strictly increasing.", call. = FALSE)
  }

  ## An unbounded tail needs a decaying envelope (finite area).
  if (!is.finite(a) && hp[1L] <= 0) {
    stop("the upper hull is improper (infinite area) on the unbounded left ",
         "tail; the leftmost log-density slope is not positive. Supply ",
         "starting values 'x0' further into the left tail.", call. = FALSE)
  }
  if (!is.finite(b) && hp[k] >= 0) {
    stop("the upper hull is improper (infinite area) on the unbounded ",
         "right tail; the rightmost log-density slope is not negative. ",
         "Supply starting values 'x0' further into the right tail.",
         call. = FALSE)
  }

  ## Log-scale segment weights: w_j propto integral of exp over [z_j, z_j+1].
  Hmax <- max(h)
  logw <- numeric(k)
  for (j in seq_len(k)) {
    L <- z[j]
    U <- z[j + 1L]
    s <- hp[j]
    span <- U - L
    if (abs(s) < 1e-300) {
      if (!is.finite(span) || span <= 0) {
        stop("improper envelope segment with zero slope on an unbounded ",
             "interval.", call. = FALSE)
      }
      logw[j] <- (h[j] - Hmax) + log(span)
    } else if (s > 0) {
      ## U is finite here (otherwise the hull would be improper, see above).
      cap <- -s * span
      logw[j] <- (h[j] - Hmax) + s * (U - x[j]) - log(s) +
        log1p(-exp(cap))
    } else {
      ## L is finite here (otherwise the hull would be improper, see above).
      cap <- s * span
      logw[j] <- (h[j] - Hmax) + s * (L - x[j]) - log(-s) +
        log1p(-exp(cap))
    }
  }
  m <- max(logw)
  if (!is.finite(m)) {
    stop("envelope weights are all zero; check the density and the domain.",
         call. = FALSE)
  }
  w <- exp(logw - m)
  list(x = x, h = h, hp = hp, z = z, w = w, wsum = sum(w),
       Hmax = Hmax, k = k)
}

# ---------------------------------------------------------------------------
# sample_envelope: draw one proposal x* from s(x) propto exp(u(x)).
# Truncated exponentials are sampled via the memoryless property, which is
# exact and overflow-safe on both finite and semi-infinite segments.
# ---------------------------------------------------------------------------
sample_envelope <- function(env) {
  r <- runif(1L, 0, env$wsum)
  cum <- cumsum(env$w)
  j <- which(r <= cum)[1L]
  if (is.na(j)) {
    j <- env$k
  }
  L <- env$z[j]
  U <- env$z[j + 1L]
  s <- env$hp[j]
  span <- U - L
  if (!is.finite(span)) {
    if (s > 0) {
      return(U - rexp(1L, s))
    }
    if (s < 0) {
      return(L + rexp(1L, -s))
    }
    stop("improper envelope segment with zero slope on an unbounded ",
         "interval.", call. = FALSE)
  }
  if (abs(s) < 1e-12) {
    return(runif(1L, L, U))
  }
  if (s > 0) {
    p <- -expm1(-s * span)
    xdraw <- U + log1p(-runif(1L) * p) / s
    return(min(max(xdraw, L), U))
  }
  p <- -expm1(s * span)
  xdraw <- L + log1p(-runif(1L) * p) / s
  min(max(xdraw, L), U)
}

# ---------------------------------------------------------------------------
# upper_hull: evaluate the piecewise-tangent upper hull u(x*) at a proposal.
# ---------------------------------------------------------------------------
upper_hull <- function(xstar, env) {
  j <- findInterval(xstar, env$z)
  j <- min(max(j, 1L), env$k)
  env$h[j] + env$hp[j] * (xstar - env$x[j])
}

# ---------------------------------------------------------------------------
# lower_hull: evaluate the chord-based squeezing function l(x*) (-Inf
# outside the current abscissa range, where no chord exists yet).
# ---------------------------------------------------------------------------
lower_hull <- function(xstar, env) {
  k <- env$k
  if (xstar <= env$x[1L] || xstar >= env$x[k]) {
    return(-Inf)
  }
  i <- findInterval(xstar, env$x)
  i <- min(max(i, 1L), k - 1L)
  env$h[i] + (env$h[i + 1L] - env$h[i]) * (xstar - env$x[i]) /
    (env$x[i + 1L] - env$x[i])
}

# ---------------------------------------------------------------------------
# ars: adaptive rejection sampler (Gilks & Wild, 1992) for log-concave
# densities.
#
# Args:
#   g:              function computing the (possibly unnormalized) density,
#                   vectorized: g(c(x1, x2)) must return c(g(x1), g(x2)).
#   n:              number of samples to draw (single positive integer).
#   a, b:           domain bounds with a < b; -Inf / Inf allowed.
#   x0:             optional starting abscissae (numeric, >= 2 distinct
#                   values inside [a, b] with positive, finite density).
#   max_proposals:  safety cap on total proposals (default 100 per sample).
#   concavity_tol:  relative tolerance for the log-concavity check
#                   h(x*) <= u(x*); smaller = stricter.
#   ...:            extra arguments passed on to g.
#
# Returns: a numeric vector of n samples from the target distribution.
# ---------------------------------------------------------------------------
ars <- function(g, n = 1000L, a = -Inf, b = Inf, x0 = NULL,
                max_proposals = NULL, concavity_tol = 1e-6, ...) {
  validate_ars_inputs(g, n, a, b, x0)
  n <- as.integer(n)
  if (is.null(max_proposals)) {
    max_proposals <- max(10000L, 100L * n)
  } else {
    if (length(max_proposals) != 1L || !is.numeric(max_proposals) ||
        is.na(max_proposals) || max_proposals < n) {
      stop("'max_proposals' must be a single number at least as large as ",
           "'n'.", call. = FALSE)
